(function(){
const M=window.OPCDemo,S=M.createStore(),$=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='home',portal='home',selected=null,tab='',filter='',status='',category='',pageNumber=1,university=0,formState=null,confirmation=null,chat=[],assistantOpen=false,detailReturn=null;
const paths={home:'/',resources:'/resources',services:'/services',funding:'/funding',challenges:'/challenges',research:'/research',news:'/news',incubation:'/incubation',policy:'/policy'};
const names={home:'首页',resources:'资源集市',services:'服务中心',funding:'融资对接',challenges:'需求广场',research:'产学研协同',news:'资讯中心',incubation:'入驻孵化',policy:'政策对接'};
function notice(text){toast(text)}
function overlay(title,content){$('#demoModal').hidden=false;$('#demoModalTitle').textContent=title;$('#demoModalBody').innerHTML=content;$('#demoModalClose').focus()}
function closeModal(){$('#demoModal').hidden=true;confirmation=null}
function syncRoute(replace=false){let url=mode==='workspace'?'/workspace?'+new URLSearchParams({role:protoRole,view:protoView}):paths[portal]||'/';if(selected&&mode==='workspace')url+='#'+new URLSearchParams({record:selected,tab});history[replace?'replaceState':'pushState'](null,'','#'+url)}
function goPortal(next='home',replace=false){portal=paths[next]?next:'home';mode=portal==='home'?'home':'portal';selected=null;filter='';status='';category='';pageNumber=1;$('#prototypeWorkspace')?.setAttribute('hidden','');$('#workspace').hidden=true;$('#portal').hidden=mode!=='home';$('#demoPortal').hidden=mode!=='portal';$('.footerV2').hidden=false;$('#loginBackdrop').hidden=true;syncRoute(replace);if(mode==='portal')renderPortal();updateNav();window.scrollTo(0,0)}
function updateNav(){$('#nav').innerHTML=Object.entries(names).filter(([id])=>!['incubation','policy'].includes(id)).map(([id,n])=>`<button data-d-portal="${id}" class="${portal===id&&mode!=='workspace'?'active':''}">${n}</button>`).join('')}
const originalNavigate=prototypeNavigate,originalRender=renderPrototype;
prototypeNavigate=function(role,view='工作台首页',replace=false){mode='workspace';selected=null;formState=null;filter='';status='';pageNumber=1;$('#demoPortal').hidden=true;originalNavigate(role,view,true);syncRoute(replace);updateNav()};
renderPrototype=function(){originalRender();if(mode==='workspace'&&protoView!=='工作台首页')renderBusiness()};
function type(){return M.typeFor(protoView)}
function record(id=selected){return S.rows.find(r=>r.id===id)}
function badge(status){return `<span class="pTag state-${E(status)}">${E(status)}</span>`}
function table(rows){return `<div class="dTableWrap"><table class="pTable"><thead><tr><th>名称 / 编号</th><th>申请主体</th><th>状态</th><th>日期</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="dTitle" data-d-record="${r.id}">${E(r.title)}</button><small>${E(r.id.toUpperCase())}</small></td><td>${E(r.company)}</td><td>${badge(r.status)}</td><td>${E(r.date)}</td><td><div class="dActions"><button data-d-record="${r.id}">查看</button>${listActions(r).map(a=>`<button data-d-entry="${E(a)}" data-id="${r.id}">${a}</button>`).join('')}</div></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有匹配的记录</div>'}</div>`}
function listActions(r){let a=M.actions(r);if(r.type==='services')return a.filter(x=>['立即处理','编辑方案'].includes(x));if(r.type==='demand')return a.filter(x=>['编辑','提交','删除','撤回','重新提交','审核','查看揭榜申请','确认中榜企业','维护协议信息','查看协议','查看交付成果','确认接收成果'].includes(x));if(r.type==='bid')return a.filter(x=>['撤回','维护交付成果'].includes(x));return a.filter(x=>['编辑','提交','撤回','审核','下架','上架','取消预约','办结'].includes(x)).slice(0,3)}
function rowsFor(){let t=type();return S.rows.filter(r=>r.type===t&&(!filter||[r.title,r.company,r.id].join(' ').includes(filter))&&(!status||r.status===status))}
function renderBusiness(){if(formState){renderForm();return}if(selected){renderDetail();return}let all=rowsFor(),limit=6,rows=all.slice((pageNumber-1)*limit,pageNumber*limit);$('.pContent').innerHTML=`<div class="pHeading"><div><small>${E(prototypeRoles[protoRole].label)} / ${E(protoView)}</small><h1>${E(protoView)}</h1></div><button class="primary" data-d-new>+ ${/成果/.test(protoView)?'新增成果':/信息管理/.test(protoView)?'新增信息':'新建申请'}</button></div><section class="pCard"><form id="demoFilter" class="dFilters"><label>关键词<input name="q" value="${E(filter)}" placeholder="名称、编号、申请主体"></label><label>状态<select name="state"><option value="">全部状态</option>${M.statusSets[type()].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></label><button class="primary">查询</button><button type="button" class="secondary" data-d-clear>重置</button><button type="button" class="secondary" data-d-export>导出</button></form>${table(rows)}${pagination(all.length,limit)}</section>`}
function pagination(total,limit=6){let count=Math.max(1,Math.ceil(total/limit));return `<div class="dPagination"><span>共 ${total} 条</span><button data-d-page="${pageNumber-1}" ${pageNumber===1?'disabled':''}>上一页</button><span>${pageNumber} / ${count}</span><button data-d-page="${pageNumber+1}" ${pageNumber>=count?'disabled':''}>下一页</button></div>`}
function openRecord(id,action='查看'){let r=record(id);if(!r)return;selected=id;formState=null;tab=M.entryTab(r.type,action);syncRoute();renderDetail()}
function tabs(r){return M.tabs(r.type).map(t=>{let locked=r.type==='services'&&((r.status==='待受理'&&t!=='受理确认')||(r.status==='方案编制中'&&!['受理确认','方案编制'].includes(t)));return `<button class="${tab===t?'active':''}" data-d-tab="${t}" ${locked?'disabled':''}>${locked?'🔒 ':''}${t}</button>`}).join('')}
function fieldsOverview(r){return `<div class="detailGrid">${M.schemas[r.type].map(([key,label])=>`<div><span>${label}</span><strong>${E(r[key]||'—')}</strong></div>`).join('')}</div>`}
function recordHistory(r){return r.history.map(h=>`<div class="dEvent"><strong>${E(h.action)}</strong><small>演示用户 · ${E(h.time)}</small><p>${E(h.note)}</p></div>`).join('')||'<p>暂无受理记录，等待受理。</p>'}
function attachments(files,id=''){return `<div class="dFiles">${files.map(f=>`<div>▤ ${E(f.name)} <small>${Math.ceil(f.size/1024)} KB</small></div>`).join('')||'<p>暂无附件材料</p>'}<label class="secondary dUpload">添加附件<input type="file" data-d-upload="${id||'record'}" accept=".pdf,.txt,.png,.jpg,.docx,.xlsx" multiple></label><small>附件仅在当前页面会话保留，不上传服务器</small></div>`}
function detailBody(r){if(tab==='融资结果')return r.result?`<p>${E(r.result)}</p>`:'<div class="empty">暂未维护融资结果</div>';if(['受理记录','办理记录'].includes(tab))return recordHistory(r);if(tab==='申请材料')return attachments(r.files);
if(tab==='审核信息'||tab==='受理确认')return `<form id="demoDecision"><label>处理结果<select name="decision"><option value="pass">${tab==='审核信息'?'审核通过':'受理通过'}</option><option value="reject">${tab==='审核信息'?'审核不通过':'驳回'}</option></select></label><label>处理意见 *<textarea name="note" required maxlength="1000" placeholder="请填写处理意见"></textarea></label><p>处理人：演示用户 · 提交后记录本地演示时间</p><button class="primary" ${!['待审核','待受理'].includes(r.status)?'disabled':''}>${tab==='审核信息'?'提交审核':'提交受理结果'}</button></form>`;
if(tab==='揭榜申请')return `<p>以下申请与当前需求按稳定ID关联。</p><table class="pTable"><thead><tr><th>企业</th><th>联系人</th><th>方案</th><th>状态</th><th>操作</th></tr></thead><tbody>${S.rows.filter(b=>b.type==='bid'&&b.demandId===r.id).map((candidate,i)=>{let n=candidate.company;return `<tr><td>${n}</td><td>演示用户</td><td><button data-d-show-plan="${i}">查看方案</button></td><td>${r.winner===n?'已选定':'待确认'}</td><td><button data-d-winner="${candidate.id}" ${!M.actions(r).includes('选定中榜企业')?'disabled':''}>选定中榜企业</button></td></tr>`}).join('')}</tbody></table>`;
if(tab==='交付成果'||tab==='过程维护')return `<div class="dStages">${r.stages.map((s,i)=>`<section class="dStage"><label>阶段名称<input data-stage="${i}" data-field="name" value="${E(s.name)}"></label><label>完成工作<textarea data-stage="${i}" data-field="work">${E(s.work)}</textarea></label>${attachments(s.files||[],'stage-'+i)}<button class="textButton" data-d-remove-stage="${i}">删除阶段</button></section>`).join('')}</div><button class="secondary" data-d-add-stage>+ 添加交付阶段</button><button class="secondary" data-d-save-stages>保存</button><p>请在保存后检查材料，再使用底部提交入口。</p>`;
if(tab==='方案编制')return `<form id="demoPlan"><div class="formGrid"><label>方案名称 *<input name="planName" value="${E(r.planName||r.title+'服务方案')}" required></label><label>预算（万元） *<input name="amount" type="number" min="0" step="0.01" value="${E(r.amount)}" required></label><label>完成日期 *<input name="date" type="date" value="${E(r.date)}" required></label><label class="wide">方案整体介绍 *<textarea name="plan" required>${E(r.plan||r.description)}</textarea></label></div><h3>实施阶段</h3>${r.stages.map((s,i)=>`<section class="dStage"><h4>阶段 ${i+1}</h4>${[['name','阶段名称'],['goal','阶段目标'],['work','工作内容'],['output','交付物'],['duration','周期']].map(([k,l])=>`<label>${l}<input name="phase-${i}-${k}" value="${E(s[k]||'')}"></label>`).join('')}</section>`).join('')}<h3>方案附件</h3>${attachments(r.planFiles||[],'plan')}<h3>其他附件</h3>${attachments(r.otherFiles||[],'other')}<button class="secondary" type="button" data-d-plan-add>添加阶段</button><button class="primary">保存草稿</button><button class="primary" name="submitPlan" value="yes">提交企业确认</button></form>`;
if(tab==='协议信息'||tab==='协议签署')return `<form id="demoAgreement"><p>协议签署为本地页面状态，不产生法律效力。</p><label>协议名称 *<input name="agreementName" required value="${E(r.agreementName||'项目协作协议')}"></label><label>约定内容 *<textarea name="agreement" required>${E(r.agreement||'双方协作范围、交付成果及时间安排。')}</textarea></label>${attachments(r.files)}<button class="primary" ${!['待维护协议','协议待确认'].includes(r.status)?'disabled':''}>保存并确认协议</button></form>`;
if(tab==='提交报告')return `<form id="demoReport"><label>服务报告 *<textarea name="report" required>${E(r.report||'')}</textarea></label>${attachments(r.files)}<button class="primary" ${r.status!=='服务中'?'disabled':''}>提交报告并申请验收</button></form>`;
if(r.type==='funding'&&tab==='基本信息')return `<h3>${E(r.fund||'OPC青创基金')}</h3><p>支持种子期及初创期创新项目，面向技术研发、场景验证与成果转化。</p><p>申请流程：完善申请资料 → 材料受理 → 项目对接 → 结果维护。</p><p>对接联系人：园区服务团队</p>`;
return fieldsOverview(r)}
function renderDetail(){let r=record();if(!r){selected=null;renderBusiness();return}$('.pContent').innerHTML=`<button class="textButton" data-d-list>← 返回${E(protoView)}</button><section class="pCard dDetailHeader"><div><small>${E(r.id.toUpperCase())}</small><h1>${E(r.title)}</h1><p>${E(r.company)} · ${E(r.date)}</p></div>${badge(r.status)}</section><div class="pTabs dDetailTabs">${tabs(r)}</div><section class="pCard dDetailBody">${detailBody(r)}</section><div class="dActionBar"><span>当前状态：${E(r.status)}</span><div class="dActions">${M.actions(r).filter(a=>!['立即处理','查看揭榜申请','确认中榜企业','维护协议信息','维护交付成果','查看协议','查看交付成果','编辑方案','审核','维护过程','保存协议','提交企业确认','提交报告','确认协议','审核通过','审核不通过','受理通过','驳回'].includes(a)).map(a=>`<button class="${['提交','提交最终成果','确认接收成果','验收通过'].includes(a)?'primary':'secondary'}" data-d-entry="${a}" data-id="${r.id}">${a}</button>`).join('')}</div></div>`}
function fieldMarkup(f,value=''){let [key,label,kind,opts]=f,optional=kind==='optional';return `<label class="${kind==='textarea'?'wide':''}">${label}${optional?'':' *'}${kind==='select'?`<select name="${key}" required>${opts.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select>`:kind==='textarea'?`<textarea name="${key}" ${optional?'':'required'} maxlength="3000">${E(value)}</textarea>`:`<input name="${key}" type="${['number','date','email','tel'].includes(kind)?kind:'text'}" ${optional?'':'required'} ${kind==='number'?'min="0" step="0.01"':''} value="${E(value)}" maxlength="200">`}</label>`}
function newForm(t=type(),values={},editId=null){formState={type:t,values:{...values},step:0,editId,files:editId?record(editId).files:[]};selected=null;mode='workspace';renderForm()}
function renderForm(){let f=formState;let fields=M.schemas[f.type],chunks=f.type==='admission'?[fields.slice(0,8),fields.slice(8,10),fields.slice(10),[]]:[fields];let steps=['申请人基本信息','项目创意与产品服务','入驻需求与运营计划','材料提交'];$('.pContent').innerHTML=`<button class="textButton" data-d-cancel-form>← 返回列表</button><section class="pCard"><h1>${f.editId?'编辑资料':'填写申请'}</h1>${f.type==='admission'?`<div class="dFormSteps">${steps.map((s,i)=>`<span class="${i===f.step?'active':''}">${i+1}. ${s}</span>`).join('')}</div>`:''}<form id="demoBusinessForm"><div class="formGrid">${chunks[f.step].map(field=>fieldMarkup(field,f.values[field[0]]||'')).join('')}</div>${f.type==='admission'&&f.step===0?'<button type="button" class="secondary" data-d-import>填入示例主体资料</button>':''}${f.step===chunks.length-1?attachments(f.files,'form'):''}<div class="formActions">${f.step?'<button type="button" class="secondary" data-d-prev>上一步</button>':''}<button type="button" class="secondary" data-d-draft>保存草稿</button><button class="primary">${f.step<chunks.length-1?'下一步':'检查并提交'}</button></div></form></section>`}
function rememberForm(){let f=$('#demoBusinessForm');if(f)Object.assign(formState.values,Object.fromEntries(new FormData(f)))}
function review(title,summary,commit){confirmation=commit;overlay(title,`<div class="dReview"><h3>请确认以下信息</h3><p>${E(summary)}</p><p>本次操作仅更新本机页面会话中的演示记录，不向原站或业务系统提交。</p><label><input type="checkbox" id="demoAcknowledge"> 我已核对资料，确认本次演示操作</label><div class="formActions"><button class="secondary" data-d-close-modal>返回修改</button><button class="primary" id="demoCommit" disabled>确认提交</button></div></div>`)}
function success(title,id){overlay('操作已完成',`<div class="dSuccess">✓</div><h3>${E(title)}</h3><p>记录编号：${E(id||'当前演示会话')}</p><p>已更新本地演示状态，可返回列表查看。</p><button class="primary" data-d-close-modal>完成</button>`)}
function submitForm(draft=false){rememberForm();let f=formState;if(!draft&&(!f.values.title||!f.values.company&&f.type==='admission')){notice('请完善项目名称及主体资料');return}let save=()=>{let r=f.editId?record(f.editId):S.newRecord(f.type,f.values);Object.assign(r,f.values);r.files=f.files;if(!draft){if(!M.actions(r).includes('提交'))r.status='草稿';S.apply(r.id,'提交')}else{r.history.unshift({action:'保存草稿',time:new Date().toLocaleString('zh-CN'),note:''})}if(!draft&&f.type==='resources'&&f.values.cartKeys){for(let i=S.cart.length-1;i>=0;i--)if(f.values.cartKeys.includes(S.cart[i].key))S.cart.splice(i,1);cartBadge()}formState=null;selected=r.id;tab=M.tabs(r.type)[0];syncRoute(true);renderDetail();if(!draft)success('申请已提交',r.id);else notice('草稿已保存')};if(draft)save();else review('提交申请',f.values.title,save)}
function execute(id,action,data={}){let r=record(id);if(!r)return;if(action==='编辑'){selected=id;newForm(r.type,r,id);return}if(['审核','立即处理','编辑方案','维护过程','查看揭榜申请','确认中榜企业','维护协议信息','查看协议','查看交付成果','维护交付成果'].includes(action)){openRecord(id,action);if(action==='维护过程')tab='过程维护';renderDetail();return}if(action==='提交最终成果'&&r.stages.some(s=>!s.name.trim()||!s.work.trim())){notice('请填写每个交付阶段的名称和完成工作');return}review(action,r.title+' · '+r.status,()=>{S.apply(id,action,data);selected=id;tab=M.tabs(r.type).includes(tab)?tab:M.tabs(r.type)[0];renderBusiness();success(action+'成功',id)})}
function liveDemands(){return S.rows.filter(r=>r.type==='demand'&&!['草稿','待审核','审核不通过'].includes(r.status)).map(r=>{let sample=M.demands.find(x=>x.id===r.id);return {...sample,id:r.id,name:r.title,category:sample?.category||'企业',owner:r.company,stage:r.status==='揭榜申请中'?'揭榜报名':r.status,desc:r.description,field:r.field||sample?.field||'人工智能',budget:r.amount+'万元',deliverable:r.deliverable||sample?.deliverable||'项目方案及报告'}})}
function portalItems(){return portal==='resources'?M.resources:portal==='services'?M.institutions:portal==='funding'?M.funds:portal==='challenges'?liveDemands():portal==='research'?M.teams:portal==='news'?M.news:[]}
function renderPortal(){let list=portalItems().filter(x=>(!filter||[x.name,x.desc,x.owner].join(' ').includes(filter))&&(!category||x.category===category));$('#demoPortal').innerHTML=`<section class="dPortalHero"><small>OPC INNOVATION ECOSYSTEM</small><h1>${names[portal]}</h1><p>连接资源、专业服务与产业合作，陪伴创业项目成长。</p>${portal==='challenges'?'<button class="primary" data-d-start="demand">立即发布需求</button>':''}${portal==='services'?'<button class="primary" data-d-start="organization">服务机构入驻</button>':''}</section><section class="dPortalBody">${portal==='research'?universityPanel():''}${['incubation','policy'].includes(portal)?`<section class="pCard"><h2>${portal==='incubation'?'入驻与项目孵化':'政策支持与申报'}</h2><p>完善企业和项目资料，跟踪申请、反馈及服务进展。</p><button class="primary" data-d-start="${portal==='incubation'?'admission':'policy'}">立即申请</button></section>`:`<form id="demoPortalSearch" class="dFilters"><label>关键词<input name="q" value="${E(filter)}" placeholder="搜索名称、描述或发布单位"></label><button class="primary">搜索</button><button type="button" class="secondary" data-d-portal-reset>重置</button>${portal==='challenges'?'<button type="button" class="secondary" data-d-favorites>我的收藏</button>':''}</form><div class="dCategories">${['',...new Set(portalItems().map(x=>x.category))].map(c=>`<button data-d-category="${E(c)}" class="${category===c?'active':''}">${c||'全部'}</button>`).join('')}</div><div class="dPortalGrid">${list.slice((pageNumber-1)*6,pageNumber*6).map(portalCard).join('')||'<div class="empty">暂无匹配结果</div>'}</div>${pagination(list.length)}`}</section>`}
function portalCard(x){let resource=portal==='resources';return `<article class="pCard dPortalCard"><div class="dCardArt" aria-hidden="true">${resource?'▦':portal==='funding'?'¥':portal==='challenges'?'⚑':'✧'}</div><span class="pTag">${E(x.category)}</span><h2>${E(x.name)}</h2><p>${E(x.desc)}</p>${resource?`<p>${E(x.spec)}</p>${x.unit==='月'?`<div class="dPeriod"><button data-d-period="year" data-id="${x.id}" class="${S.periods[x.id]!=='month'?'active':''}">年租</button><button data-d-period="month" data-id="${x.id}" class="${S.periods[x.id]==='month'?'active':''}">月租</button></div>`:''}<strong class="dPrice">¥${S.price(x.id).toLocaleString()}<small>/${E(x.unit)}</small></strong><p>${S.periods[x.id]==='month'?'按月租用，按月计费':'年租按优惠单价折算；月单位资源按12个月结算'}</p><button class="primary" data-d-cart-add="${x.id}">立即申请</button>`:`${x.stage?badge(x.stage):''}<p>${E(x.owner||x.type||x.scale||x.time||'')}</p><div class="dActions"><button class="secondary" data-d-portal-detail="${x.id}">查看详情</button><button class="primary" data-d-portal-apply="${x.id}" ${['challenges','news'].includes(portal)&&x.stage&&(!['揭榜报名','报名中'].includes(x.stage))?'disabled':''}>${portal==='challenges'?'立即揭榜':portal==='news'?'立即报名':portal==='research'?'合作意向':'立即申请'}</button>${portal==='challenges'?`<button class="textButton" data-d-favorite="${x.id}">${S.favorites.has(x.id)?'★ 已收藏':'☆ 收藏'}</button>`:''}</div>`}</article>`}
function universityPanel(){let u=M.universities[university];return `<section class="pCard"><div class="dCategories">${M.universities.map((x,i)=>`<button class="${i===university?'active':''}" data-d-uni="${i}">${x.name}</button>`).join('')}</div><h2>${u.name}</h2><p>${u.direction}</p><p>团队 ${u.teams} · 成果 ${u.results} · 合作企业 ${u.companies} · ${university+1}/5</p><small>下方团队列表为独立展示，不随院所整体过滤。</small></section>`}
function portalDetail(id){let x=portalItems().find(x=>x.id===id);if(!x)return;detailReturn={portal,id};overlay(x.name,`<span class="pTag">${E(x.category)}</span><h3>项目介绍</h3><p>${E(x.desc)}</p>${portal==='funding'?`<h3>基金规模与阶段</h3><p>${E(x.scale)} · ${E(x.stage)}</p><h3>申请条件</h3><p>符合创新创业方向，具备明确的研发或商业化计划。</p><h3>申请流程</h3><p>准备资料 → 提交申请 → 材料受理 → 项目对接</p>`:portal==='challenges'?`<h3>背景与能力要求</h3><p>${E(x.desc)}。具备相关技术开发与试点实施能力。</p><h3>预期交付成果</h3><p>${E(x.deliverable)}</p><p>项目预算：${E(x.budget)}</p>`:portal==='news'?`<p>时间：${E(x.time||'资讯发布')}</p><p>地点：${E(x.place||'平台')}</p><p>报名进度：${x.people||0}/${x.capacity||0}</p><h3>适合人群</h3><p>创业团队、技术研发人员与生态合作伙伴。</p>`:`<p>${E(x.owner||x.type||'')}</p>`}<h3>联系与对接</h3><p>通过平台提交意向，由对接团队跟进。</p><button class="primary" data-d-apply-detail="${id}" ${['challenges','news'].includes(portal)&&x.stage&&(!['揭榜报名','报名中'].includes(x.stage))?'disabled':''}>${portal==='news'?'立即报名':portal==='challenges'?'立即揭榜':'立即申请'}</button>`)}
function startApplication(t,values={}){closeModal();let view={admission:'入驻申请',incubation:'项目入孵申请',resources:'资源申请管理',services:'服务申请',funding:'基金申请进度查询',demand:'需求发榜管理',bid:'我的揭榜',research:'产学研对接管理',achievement:'科研成果信息管理',organization:'服务机构入驻申请',policy:'政策申报',daily:'会议室预订',exit:'退出申请'}[t];let role=t==='demand'?'demand':t==='achievement'?'university':t==='organization'?'park':'opc';prototypeNavigate(role,view);newForm(t,values)}
function applyPortal(id){let x=portalItems().find(x=>x.id===id);if(!x)return;if(portal==='news'){portalDetail(id);return}let t={services:'services',funding:'funding',challenges:'bid',research:'research'}[portal];startApplication(t,{title:x.name,description:x.desc,fund:portal==='funding'?x.name:'',partner:portal==='research'?x.name:'',demandId:portal==='challenges'?x.id:undefined})}
function cartPanel(){overlay('资源购物车',S.cart.length?`<div>${S.cart.map(x=>`<div class="dCartRow"><strong>${E(x.name)}</strong><small>${x.period==='year'?'年租':'月租'} · ¥${x.price}/${x.unit}</small><label>数量<input type="number" min="1" max="999" data-d-cart-qty="${x.key}" value="${x.quantity}"></label><button class="textButton" data-d-cart-remove="${x.key}">移除</button></div>`).join('')}</div><h3>合计 ¥${S.total().toLocaleString()}</h3><p>年租的月单价按12个月计算。数量和总价为本地演示计算。</p><button class="primary" data-d-cart-checkout>填写批量申请</button>`:'<div class="empty">购物车为空，先从资源集市添加资源。</div>')}
function cartBadge(){$('#demoCart').textContent='▦ 购物车 ('+S.cart.reduce((n,x)=>n+x.quantity,0)+')'}
function chatRender(){
  const questions=chat.length?['入孵申请流程','扶持政策','算力资源']:['入孵申请流程','扶持政策','算力资源','需求广场','产学研合作','入孵条件'];
  const widget=$('#assistantWidget');
  widget.innerHTML=`<div class="assistantHead">
    <div><b id="assistantTitle">小启 · OPC 创业助手</b><small>在线 · 访客模式</small></div>
    <div class="assistantControls"><button type="button" data-d-chat-reset>重置</button><button type="button" data-d-chat-close aria-label="收起小启">−</button></div>
  </div>
  <div class="assistantBody" id="assistantBody">
    <div class="dMessage dChatWelcome bot">
      <svg aria-hidden="true" width="34" height="34"><use href="#xiaoqi-avatar"></use></svg>
      <div><strong>你好，我是小启！</strong><p>想申请入驻、找算力资源，或了解创业扶持政策？选一个常见问题，或者直接问我。</p><small>${new Date().toLocaleTimeString('zh-CN',{hour12:false})}</small></div>
    </div>
    ${chat.map(m=>`<div class="dMessage ${m.role}"><p>${m.role==='bot'?m.text.split('\n').map((line,i)=>i===0?'<strong>'+E(line)+'</strong>':E(line)).join('<br>'):E(m.text).replace(/\n/g,'<br>')}</p><small>${m.time}</small></div>`).join('')}
  </div>
  <div class="assistantQuestions">${questions.map(q=>`<button data-d-question="${q}">${q}</button>`).join('')}</div>
  <form id="demoChat"><input name="message" aria-label="向小启提问" placeholder="请输入您的问题" autocomplete="off"><button class="primary" id="demoChatSend" disabled>发送</button></form>
  <p class="dChatNote">模拟回复仅供参考，不代表园区官方意见。</p>`;
  widget.hidden=!assistantOpen;
  $('#assistantToggle').setAttribute('aria-expanded',String(assistantOpen));
}
function ask(q){if(!q.trim())return;let time=new Date().toLocaleTimeString('zh-CN',{hour12:false});let userText=q==='入孵申请流程'?'请介绍一下入驻园区的申请流程':q;let answer=/申请|入孵|条件|流程/.test(q)?'入孵服务导览：\n1. 扫码申请，完善主体与项目资料。\n2. AI预审，核对材料。\n3. 专家评审，沟通项目方向。\n4. 空间分配，对接入驻需求。\n5. 一键建档，持续跟踪服务。\n页面展示流程与首页四步口径存在差异，以具体办理要求为准。':/政策/.test(q)?'可在政策对接中查看适合的政策方向，完善企业与项目资料后提交申报。具体条件和结果以正式发布及审核为准。':/算力|资源/.test(q)?'进入资源集市，选择单卡或多卡资源及独立租期，加入购物车后统一填写申请资料。':/需求|揭榜/.test(q)?'进入需求广场查看需求背景、能力与交付要求；报名阶段可填写揭榜方案，并在我的揭榜中跟踪交付。':/产学研|合作/.test(q)?'在产学研协同查看院所、团队及成果，填写合作主题与意向，提交后在工作台查看进度。':'可以从入孵流程、扶持政策、算力资源、需求广场和产学研合作选择问题。本助手使用预设导览，不连接真实AI服务。';chat.push({role:'user',text:userText,time},{role:'bot',text:answer,time});chatRender();$('#assistantBody').scrollTop=$('#assistantBody').scrollHeight}
function upload(input){let files=Array.from(input.files||[]);if(files.some(f=>f.size>5*1024*1024)){notice('单个附件不能超过5 MB');input.value='';return}let data=files.map(f=>({name:f.name,size:f.size,type:f.type}));let key=input.dataset.dUpload;if(key==='form'){formState.files.push(...data);rememberForm();renderForm()}else if(['plan','other'].includes(key)){let r=record();r[key+'Files']||=[];r[key+'Files'].push(...data);renderDetail()}else if(key.startsWith('stage-')){record().stages[Number(key.slice(6))].files.push(...data);renderDetail()}else{record().files.push(...data);renderDetail()}}
function restore(){if(location.hash.startsWith('#prototype?')){let q=new URLSearchParams(location.hash.split('?')[1]);prototypeNavigate(q.get('role')||'park',q.get('view')||'工作台首页',true);return}let local=new URL(location.hash.slice(1)||'/', 'https://demo.invalid');let p=local.pathname;if(p==='/workspace'){let q=new URLSearchParams(local.search),h=new URLSearchParams(local.hash.slice(1));prototypeNavigate(q.get('role')||'park',q.get('view')||'工作台首页',true);if(h.get('record')&&record(h.get('record'))){selected=h.get('record');tab=M.tabs(record().type).includes(h.get('tab'))?h.get('tab'):M.tabs(record().type)[0];renderDetail()}return}let key=Object.keys(paths).find(k=>paths[k]===p);if(key)goPortal(key,true)}
function legacy(b,e){let stop=()=>{e.preventDefault();e.stopImmediatePropagation();return true};if(b.id==='headerAction'){prototypeNavigate(protoRole);return stop()}if(b.dataset.go!==undefined){goPortal({financing:'funding',bid:'challenges',admission:'incubation',home:'home'}[b.dataset.go]||b.dataset.go);return stop()}if(['applyBtn','spaceApply'].includes(b.id)){startApplication('admission');return stop()}if(b.hasAttribute('data-p-password')){overlay('修改密码',`<form id="demoPassword"><p>此表单仅验证输入，不修改任何真实账号。</p><label>当前密码<input type="password" name="old" required></label><label>新密码<input type="password" name="next" minlength="8" required></label><label>确认新密码<input type="password" name="confirm" required></label><button class="primary">检查并提交</button></form>`);return stop()}if(b.hasAttribute('data-p-logout')){goPortal();$('#protoAccountMenu').hidden=true;notice('已退出前端角色工作台');return stop()}if(b.dataset.pFeedback||b.dataset.pShort){let target=b.dataset.pFeedback||b.dataset.pShort;if(/会议|预约|日程/.test(target))prototypeNavigate(protoRole,'会议室预订');else if(/揭榜/.test(target))prototypeNavigate(protoRole,'我的揭榜');else if(/项目/.test(target))prototypeNavigate(protoRole,'项目信息管理');else if(/政策/.test(target))prototypeNavigate(protoRole,'政策申报');else{let first=Object.values(prototypeRoles[protoRole].menus).flat()[0];prototypeNavigate(protoRole,first)}return stop()}return false}
window.OPCApp={handleLegacy:legacy,store:S};
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-go]');if(!b)return;if(b.dataset.go!==undefined){legacy(b,e);return}let handled=true;
if(b.dataset.dPortal)goPortal(b.dataset.dPortal);
else if(b.hasAttribute('data-d-new'))newForm();
else if(b.dataset.dRecord)openRecord(b.dataset.dRecord);
else if(b.dataset.dEntry)execute(b.dataset.id,b.dataset.dEntry);
else if(b.dataset.dTab){tab=b.dataset.dTab;syncRoute(true);renderDetail()}
else if(b.hasAttribute('data-d-list')||b.hasAttribute('data-d-cancel-form')){selected=null;formState=null;syncRoute();renderBusiness()}
else if(b.hasAttribute('data-d-clear')){filter='';status='';pageNumber=1;renderBusiness()}
else if(b.dataset.dPage){pageNumber=Math.max(1,Number(b.dataset.dPage));mode==='portal'?renderPortal():renderBusiness()}
else if(b.hasAttribute('data-d-draft'))submitForm(true);
else if(b.hasAttribute('data-d-prev')){rememberForm();formState.step--;renderForm()}
else if(b.hasAttribute('data-d-import')){rememberForm();Object.assign(formState.values,{company:'示例科技有限公司',contact:'演示用户',phone:'00000000000',email:'demo@example.invalid'});renderForm()}
else if(b.dataset.dPortalDetail)portalDetail(b.dataset.dPortalDetail);
else if(b.dataset.dPortalApply){portal==='news'?portalDetail(b.dataset.dPortalApply):applyPortal(b.dataset.dPortalApply)}
else if(b.dataset.dApplyDetail){if(portal==='news'){let x=M.news.find(x=>x.id===b.dataset.dApplyDetail);review('确认活动报名',x.name,()=>{let r=S.newRecord('daily',{title:x.name,category:'活动报名',company:'示例科技有限公司'},'待确认');success('报名已提交',r.id)})}else applyPortal(b.dataset.dApplyDetail)}
else if(b.dataset.dStart)startApplication(b.dataset.dStart);
else if(b.dataset.dPeriod){S.periods[b.dataset.id]=b.dataset.dPeriod;renderPortal()}
else if(b.dataset.dCartAdd){S.addCart(b.dataset.dCartAdd);cartBadge();notice('已加入资源购物车')}
else if(b.id==='demoCart')cartPanel();
else if(b.dataset.dCartRemove){S.cart.splice(S.cart.findIndex(x=>x.key===b.dataset.dCartRemove),1);cartBadge();cartPanel()}
else if(b.hasAttribute('data-d-cart-checkout')){let snapshot=S.cart.map(x=>({...x}));startApplication('resources',{title:'资源批量申请',cartKeys:snapshot.map(x=>x.key),description:snapshot.map(x=>x.name+' / '+(x.period==='year'?'年租':'月租')+' / 数量'+x.quantity).join('\n')+'\n合计：¥'+S.total()})}
else if(b.hasAttribute('data-d-category')){category=b.dataset.dCategory;pageNumber=1;renderPortal()}
else if(b.hasAttribute('data-d-portal-reset')){category='';filter='';pageNumber=1;renderPortal()}
else if(b.dataset.dFavorite){S.favorites.has(b.dataset.dFavorite)?S.favorites.delete(b.dataset.dFavorite):S.favorites.add(b.dataset.dFavorite);renderPortal()}
else if(b.hasAttribute('data-d-favorites')){let rows=liveDemands().filter(x=>S.favorites.has(x.id));overlay('我的收藏',rows.map(x=>`<button class="pRow" data-d-portal-detail="${x.id}">${x.name} →</button>`).join('')||'<p>暂无收藏</p>')}
else if(b.hasAttribute('data-d-uni')){university=Number(b.dataset.dUni);renderPortal()}
else if(b.id==='demoModalClose'||b.hasAttribute('data-d-close-modal'))closeModal();
else if(b.id==='demoCommit'){let fn=confirmation;if(fn){confirmation=null;fn()}}
else if(b.hasAttribute('data-d-add-stage')){record().stages.push({name:'',work:'',files:[]});renderDetail()}
else if(b.hasAttribute('data-d-remove-stage')){record().stages.splice(Number(b.dataset.dRemoveStage),1);renderDetail()}
else if(b.hasAttribute('data-d-save-stages')){record().history.unshift({action:'保存交付阶段',time:new Date().toLocaleString('zh-CN'),note:''});notice('交付阶段已保存')}
else if(b.hasAttribute('data-d-plan-add')){let f=$('#demoPlan');Object.assign(record(),Object.fromEntries(new FormData(f)));record().stages.push({name:'新增阶段',work:'',files:[]});renderDetail()}
else if(b.hasAttribute('data-d-show-plan'))overlay('揭榜方案',`<h3>方案${Number(b.dataset.dShowPlan)+1}</h3><p>采用轻量化模型完成场景验证，按需求分析、系统设计、开发实施三个阶段交付。</p>`);
else if(b.dataset.dWinner)execute(selected,'选定中榜企业',{data:{winner:record(b.dataset.dWinner).company,winnerId:b.dataset.dWinner}});
else if(b.id==='assistantToggle'){assistantOpen=!assistantOpen;chatRender()}
else if(b.hasAttribute('data-d-chat-close')||b.id==='closeAssistant'){assistantOpen=false;chatRender()}
else if(b.hasAttribute('data-d-chat-reset')){chat=[];chatRender()}
else if(b.dataset.dQuestion)ask(b.dataset.dQuestion);
else if(b.id==='demoReset')review('重置当前演示','清空本页面会话的演示记录、购物车与附件信息；不会影响SQLite库。',()=>{S.reset();chat=[];selected=null;formState=null;cartBadge();mode==='workspace'?renderPrototype():goPortal(portal,true);success('演示已重置')});
else if(b.hasAttribute('data-d-export')){let rows=rowsFor(),text='名称,编号,状态\n'+rows.map(r=>[r.title,r.id,r.status].map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv'}));a.download='OPC业务记录.csv';a.click();URL.revokeObjectURL(a.href)}
else handled=false;
if(handled){e.preventDefault();e.stopImmediatePropagation()}
},true);
document.addEventListener('submit',e=>{let f=e.target;let ids=['demoFilter','demoPortalSearch','demoBusinessForm','demoDecision','demoPlan','demoAgreement','demoReport','demoChat','demoPassword','progressForm'];if(!ids.includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();let v=Object.fromEntries(new FormData(f));
if(f.id==='demoFilter'){filter=v.q;status=v.state;pageNumber=1;renderBusiness()}
if(f.id==='demoPortalSearch'){filter=v.q;pageNumber=1;renderPortal()}
if(f.id==='demoBusinessForm'){rememberForm();if(formState.type==='admission'&&formState.step<3){formState.step++;renderForm()}else submitForm()}
if(f.id==='demoDecision')execute(selected,tab==='审核信息'?(v.decision==='pass'?'审核通过':'审核不通过'):(v.decision==='pass'?'受理通过':'驳回'),{note:v.note});
if(f.id==='demoPlan'){let r=record();let data={...v};r.stages.forEach((s,i)=>{for(let k of ['name','goal','work','output','duration'])if(v['phase-'+i+'-'+k]!==undefined)s[k]=v['phase-'+i+'-'+k]});if(e.submitter?.name==='submitPlan')execute(selected,'提交企业确认',{data});else{Object.assign(r,data);notice('方案草稿已保存')}}
if(f.id==='demoAgreement')execute(selected,record().type==='services'?'确认协议':'保存协议',{data:v});
if(f.id==='demoReport')execute(selected,'提交报告',{data:v});
if(f.id==='demoChat')ask(v.message);
if(f.id==='demoPassword'){if(v.next!==v.confirm){notice('两次新密码不一致');return}review('确认密码表单', '本操作仅演示校验结果，不变更原有账号密码。',()=>success('密码表单校验通过'))}
if(f.id==='progressForm'){let query=String(v.query||'').trim();let r=S.rows.find(x=>x.type==='admission'&&(x.id.toLowerCase().includes(query.toLowerCase())||x.company.includes(query)));overlay('查询申请进度',r?`<h3>${E(r.company)}</h3><p>${E(r.title)} · ${E(r.id)}</p>${badge(r.status)}${recordHistory(r)}`:'<p>未找到匹配记录，请输入申请编号或主体名称。</p>')}
},true);
document.addEventListener('input',e=>{let el=e.target;if(el.closest('#demoChat'))$('#demoChatSend').disabled=!el.value.trim();if(el.dataset.stage!==undefined){let s=record()?.stages[Number(el.dataset.stage)];if(s)s[el.dataset.field]=el.value}});
document.addEventListener('change',e=>{let el=e.target;if(el.id==='demoAcknowledge')$('#demoCommit').disabled=!el.checked;if(el.dataset.dUpload)upload(el);if(el.dataset.dCartQty){let item=S.cart.find(x=>x.key===el.dataset.dCartQty);item.quantity=Math.max(1,Math.min(999,Number(el.value)||1));cartBadge();cartPanel()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();assistantOpen=false;chatRender()}if(e.key==='Enter'&&e.target.matches('.serviceCardV2')){e.preventDefault();e.stopImmediatePropagation();goPortal({admission:'incubation',financing:'funding',bid:'challenges'}[e.target.dataset.go]||e.target.dataset.go)}},true);
window.addEventListener('popstate',restore);
window.addEventListener('load',()=>{
document.body.insertAdjacentHTML('beforeend','<div class="modalBackdrop" id="demoModal" hidden><section class="modal dModal" role="dialog" aria-modal="true" aria-labelledby="demoModalTitle"><button id="demoModalClose" class="close" aria-label="关闭详情">×</button><h2 id="demoModalTitle"></h2><div id="demoModalBody"></div></section></div><button id="demoCart" class="dCartFloat">▦ 购物车 (0)</button>');
let main=document.createElement('main');main.id='demoPortal';main.hidden=true;$('#portal').after(main);
$('.topright').insertAdjacentHTML('beforeend','<button id="demoReset" title="恢复当前会话的前端演示样本">重置演示</button>');
document.body.append($('#assistantWidget'),$('#assistantToggle'));chatRender();updateNav();restore();
});
})();
